args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?husband ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Mok_Kwai-lan dbp:spouse ?husband .
  OPTIONAL { ?husband (dbo:birthPlace|dbp:birthPlace) ?birthPlace . }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel) = "en") }
}

